    77                  else                                                                  \
    78                          (_body)->last_param->next = (_param);                             \
    79                  (_body)->last_param = (_param);                                       \
    80                  if((_param)->type == TAG_PARAM)                                       \
    81                          memcpy(&((_body)->tag_value), &((_param)->value), sizeof(str));   \
