    45  int parse_to_header(struct sip_msg *const msg)
    46  {
    47          if(!msg->to && (parse_headers(msg, HDR_TO_F, 0) == -1 || !msg->to)) {
    48                  LM_ERR("bad msg or missing TO header\n");
    49                  return -1;
    50          }
    51
    52          // HDR_TO_T is automatically parsed (get_hdr_field in parser/msg_parser.c)
    53          // so check only ptr validity
    54          if(msg->to->parsed)
    55                  return 0;
    56          else
    57                  return -1;
    58  }
