    60  sip_uri_t *parse_to_uri(sip_msg_t *const msg)
    61  {
    62          to_body_t *tb = NULL;
    63
    64          if(msg == NULL)
    65                  return NULL;
    66
    67          if(parse_to_header(msg) < 0) {
    68                  LM_ERR("cannot parse TO header\n");
    69                  return NULL;
    70          }
    71
    72          if(msg->to == NULL || get_to(msg) == NULL)
    73                  return NULL;
    74
    75          tb = get_to(msg);
    76
    77          if(tb->parsed_uri.user.s != NULL || tb->parsed_uri.host.s != NULL)
    78                  return &tb->parsed_uri;
    79
    80          if(parse_uri(tb->uri.s, tb->uri.len, &tb->parsed_uri) < 0) {
    81                  LM_ERR("failed to parse To uri\n");
    82                  memset(&tb->parsed_uri, 0, sizeof(struct sip_uri));
    83                  return NULL;
    84          }
    85
    86          return &tb->parsed_uri;
    87  }
